if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }

var ribbons = [];
var numRibbons = 5;
var ribbonPalette = ['#e63946', '#2a9d8f', '#e76f51', '#ffb703', '#1d3557'];
var goldDust = [];

function RibbonPath(idx) {
    this.idx = idx;
    this.colStr = ribbonPalette[idx % ribbonPalette.length];
    this.pts = [];
    this.reset();
}
RibbonPath.prototype.reset = function() {
    this.pts = [];
    var startY = height * 0.2 + this.idx * (height * 0.15);
    for (var x = 0; x < width + 100; x += 20) {
        this.pts.push(createVector(x, startY));
    }
};
RibbonPath.prototype.update = function(beat, low) {
    var t = frameCount * 0.015;
    for (var i = 0; i < this.pts.length; i++) {
        var pt = this.pts[i];
        var waveY = sin(t * 2 + i * 0.15 + this.idx) * (30 + low * 40);
        var waveX = cos(t * 1.5 + i * 0.1) * 15;
        pt.y += waveY * 0.05;
        pt.x += waveX * 0.02;
    }
};
RibbonPath.prototype.draw = function(beat) {
    stroke(this.colStr);
    strokeWeight(6 + beat * 6);
    noFill();
    beginShape();
    for (var i = 0; i < this.pts.length; i++) {
        var pt = this.pts[i];
        curveVertex(pt.x, pt.y);
    }
    endShape();
};

function setup() {
    createCanvas(windowWidth, windowHeight);
    background(15, 12, 16);
    for (var i = 0; i < numRibbons; i++) {
        ribbons.push(new RibbonPath(i));
    }
    for (var i = 0; i < 200; i++) {
        goldDust.push({
            x: random(width),
            y: random(height),
            r: random(1, 4),
            speed: random(0.5, 2.0)
        });
    }
}

function draw() {
    fill(15, 12, 16, 40);
    rect(0, 0, width, height);

    var beat = (window.beatEnergy || 0.0);
    var low = (window.audioLow || 0.5);

    noStroke();
    fill('#ffd700');
    for (var i = 0; i < goldDust.length; i++) {
        var g = goldDust[i];
        g.y -= g.speed;
        if (g.y < 0) g.y = height;
        circle(g.x, g.y, g.r * (1.0 + beat * 0.5));
    }

    for (var i = 0; i < ribbons.length; i++) {
        var r = ribbons[i];
        r.update(beat, low);
        r.draw(beat);
    }
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
